mapper.select:
select r.*
from lab_reservation r
where 1 = 1

    and r.reservation_no like concat('%', #{reservationNo}, '%')


    and r.lab_id = #{labId}


    and r.applicant_user_id = #{applicantUserId}


    and r.approver_user_id = #{approverUserId}


    and r.status = #{status}


    and exists (
        select 1
        from lab_reservation_slot s
        where s.reservation_id = r.id
          and s.reservation_date = #{reservationDate}
    )

order by r.id desc
limit #{offset}, #{pageSize}

select count(*)
from lab_reservation r
where 1 = 1

    and r.reservation_no like concat('%', #{reservationNo}, '%')


    and r.lab_id = #{labId}


    and r.applicant_user_id = #{applicantUserId}


    and r.approver_user_id = #{approverUserId}


    and r.status = #{status}


    and exists (
        select 1
        from lab_reservation_slot s
        where s.reservation_id = r.id
          and s.reservation_date = #{reservationDate}
    )

select *
from lab_reservation
where applicant_user_id = #{userId}
order by id desc
limit #{offset}, #{pageSize}

select count(*)
from lab_reservation
where applicant_user_id = #{userId}

mapper.update:
update lab_reservation
set approver_user_id = #{approverUserId},
    status = #{status},
    reject_reason = #{rejectReason}
where id = #{id}

update lab_reservation
set status = 4
where id = #{id}

update lab_reservation
set check_in_time = now()
where id = #{id}

mapper.select:
select r.reservation_type as name, count(distinct r.id) as count
from lab_reservation r
join lab_reservation_slot s on s.reservation_id = r.id
where 1 = 1

    and s.reservation_date  >=  #{startDate}


    and s.reservation_date  <=  #{endDate}


    and r.lab_id = #{labId}

group by r.reservation_type

select r.status as name, count(distinct r.id) as count
from lab_reservation r
join lab_reservation_slot s on s.reservation_id = r.id
where 1 = 1

    and s.reservation_date  >=  #{startDate}


    and s.reservation_date  <=  #{endDate}


    and r.lab_id = #{labId}

group by r.status

select l.lab_name as name, count(distinct r.id) as count from lab l left join lab_reservation r on l.id = r.lab_id left join lab_reservation_slot s on s.reservation_id = r.id where l.deleted = 0
and l.department_id = #{departmentId}
and l.id = #{labId}
and (r.id is null or s.reservation_date >= #{startDate})
and (r.id is null or s.reservation_date <= #{endDate})
group by l.id, l.lab_name order by count desc, l.id asc

select p.period_name as name, count(*) as count
from lab_reservation_slot s
join lab_reservation r on r.id = s.reservation_id
join class_period p on p.id = s.period_id
where 1 = 1

    and s.reservation_date  >=  #{startDate}


    and s.reservation_date  <=  #{endDate}


    and r.lab_id = #{labId}

group by p.id, p.period_name
order by p.sort_order asc, p.period_no asc

select date_format(s.reservation_date, '%Y-%m-%d') as name, count(distinct r.id) as count from lab_reservation_slot s join lab_reservation r on r.id = s.reservation_id where 1 = 1
and s.reservation_date >= #{startDate}
and s.reservation_date <= #{endDate}
group by s.reservation_date order by s.reservation_date asc
